// DEV-ONLY harness. Phase 2's chat agent calls these tools directly through Execute Workflow;
// this webhook exists so the tools can be exercised end-to-end (real trigger -> real sub-workflow
// -> real Postgres) before any agent exists, and so the QA script can assert their JSON.
const IDS = {
  "find_availability": "3c848KpKWiiZL6h3",
  "create_booking": "DWCOVNsoknq6dDGj",
  "cancel_booking": "QIjfO7qhZyyRWQEa",
  "find_stylist_alternatives": "KC8NpsjweuihtSJN",
  "chat": "TEJeu6nUC9Xg0adO",
  "send_notification": "6EOMx2mTG4SiFTzs",
  "reminder_sweep": "A0uu84y7E26yjjAu",
  "backfill_run": "3UFfejiIFZ3B3cr5",
  "stylist_decline": "0VBOoPPgzC9fSvhR",
  "reassign_booking": "j6acFrnjcU64xsrP"
};
const out = [];
for (const item of $input.all()) {
  const body = (item.json && item.json.body) || {};
  const tool = String(body.tool || '').trim();
  const id = IDS[tool];
  if (!id) return [{ json: { _unknown_tool: tool, ok: false, reason: 'unknown_tool' } }];
  // `inputs: [...]` fans out, so the multi-item contract can be exercised: a Code node that
  // reads $json instead of $input.all() collapses this to one item and silently drops bookings.
  const many = Array.isArray(body.inputs) ? body.inputs : null;
  for (const one of (many || [body.input || {}])) {
    out.push({ json: Object.assign({}, one, { _workflow_id: id }) });
  }
}
return out;
